// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 gSeed, address actor) public {
        vm.assume(actor != address(0));
        bytes32 g = bytes32(gSeed);

        uint256 targetBlock = block.number + 1; // lockInGuess stores block.number + 1

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // move past the target block (within 256 blocks so the hash is nonzero)
        vm.roll(block.number + 2);
        bytes32 answer = blockhash(targetBlock);

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference rule: settle() succeeds exactly for a LOSING guess (g != answer);
        // a winning guess would attempt a 2-ether payout that reverts (balance is 1 ether).
        // The mutant pays losers instead, so its payout attempt reverts on every losing guess.
        assertTrue(ok == (g != answer));
    }
}
